ns.AddQuests("z10", {
    { id = 98447, name = "The Valor Family", level = 27, minLevel = 18, steps = { { name = "Ol' Sandy", area = 10, x = 17.7, y = 53.6 } }, objective = "Find the cause of the Valor family ghosts in Raven Hill for Sirra Von'Indi in Darkshire.", desc = "Despite you putting down the Valor family ghosts, the reports of attacks have not ceased. It was a good gamble, but perhaps we did not settle their unfinished business after all.\n\nFrom my research, it sounds like this family all went missing at the same time. Whatever trauma caused their spirits to be chained to this realm must have happened all at once.\n\nOur only clue is where you found the book. Return to Raven Hill and see what you can find. Maybe bringing their weapons will spark something." },
})

ns.AddQuests("z11", {
    { id = 98072, name = "Crocs of the Sky", level = 27, minLevel = 19, faction = "Alliance", steps = { { name = "Pristine Crimson Scale", area = 11, x = 63.8, y = 45.2 } }, objective = "Collect 10 Pristine Crimson Scales and bring them to James Halloran in Menethil Harbor.", desc = "You're quite the go-getter! I have just one more favor to ask, if you're up for something a bit more dangerous.\n\nThe crocolisk trade is steady money, but they're small fish compared to what whelp scales will bring. Folks will pay top dollar for a sack of those.\n\nCrocs of the sky, I call 'em! There's no way my apprentice could get them--but it seems right up your alley!\n\nYou'll find whelps far to the east, along the Green Belt. But be careful, there's nasty orcs in those hills!" },
    { id = 98208, name = "Bloom of the Heavens", level = 29, minLevel = 22, faction = "Alliance", objective = "Recover Nord'el for Sylessa Duskwhisper in Menethil Harbor.", desc = "I came to Menethil Harbor from Auberdine, from the great tree Teldrassil, to recover a bloom of great import to my people.\n\nMy people's ship the Flying Osprey crashed here many moons ago, joined with the Kul Tiran Third Fleet. Among its cargo was the flower known as Nord'el--Bloom of the Heavens in your tongue--bloomed under a full moon at the peak of Mount Hyjal, our former home.\n\nPlease help me retrieve it! The wreckage is just south of the city, but it is inhabited by fierce murloc raiders!" },
})

ns.AddQuests("z12", {
    { id = 95771, name = "A Taste of Darkness", level = 10, minLevel = 6 },
})

ns.AddQuests("z141", {
    { id = 97979, name = "The Goddess Provides", level = 1, minLevel = 1, faction = "Alliance", giver = "Shanda", start = { npc = "Shanda", area = 141, x = 59.2, y = 40.4 }, finish = { npc = "Shanda", area = 141, x = 59.2, y = 40.4 }, objective = "Cast Elune's Light and Shadowmeld.", desc = "You are born kaldorei--the children of the stars--and have inherited a birthright unlike any other in this world. Elune's grace may illuminate our strengths, helping our strikes hit true, or it may help conceal us just as the moon may eclipse the sun.\n\nOur Long Vigil after the defense of Mount Hyjal has ended, and we have joined an Alliance of others--which you will meet in due time. For now, you are nestled in the boughs of Teldrassil.\n\nDemonstrate Mother Moon's gifts, and bask in her blessings." },
})

ns.AddQuests("z1537", {
    { id = 95818, name = "A Quick Craft", level = 60, minLevel = 1, requires = { 95817 }, objective = "Bring the requested materials to Rotgath Stonebeard near the Great Forge in Ironforge.", desc = "We can get ye sorted out and out of here in no time, provided you have the materials on hand! We are going to need 25 Mithril Bars and 15 Heavy Leather. Normally we need some other metals and the like too, but I've got some scrap that's been taking up space we can use for those extra bits.\n\nOh, as a personal favor, I am gonnae ask for 5 Goldthorn as well. My wife knows a great recipe for tea and I'd like to surprise her. Consider this your payment!" },
})

ns.AddQuests("z16593", {
    { id = 92454, name = "Welcome!", level = 1, minLevel = 1, objective = "Bring the Thendal Grove Gift Voucher to Dalia Windbreeze.", desc = "Welcome to the World of Warcraft!\n\nAs special thanks for purchasing the World of Warcraft Collector's Edition, turn in this gift voucher to Dalia Windbreeze in Thendal Grove.  You'll then be given a gift: a little companion to join you on your quest for adventure and glory.\n\nThanks again, and enjoy your stay in the World of Warcraft!" },
    { id = 94898, name = "Violent Winds (Temp Disabled)", level = 11, minLevel = 8, steps = { { name = "Wind Hollow", area = 16593, x = 57.9, y = 32.1 } }, objective = "Slay 10 Wind Hollows.", desc = "When our home started to fall into the sky that fateful night, its as if the elements themselves were waiting to consume us. Wind spirits began appearing as we were fleeing, and to our dismay they began attacking the fleeing survivors.\n\nWe lost many villagers to the sky, but even more to the relentless anger of those wind spirits. I don't know if it was our village falling into the sky, but they are extremely dangerous.\n\nIf you are able, please put them to rest." },
    { id = 94901, name = "Hopping Helpers", level = 11, minLevel = 8, objective = "Collect $1oa Gustjumper frogs.", desc = "[PH] Collect frogs" },
    { id = 94902, name = "Valanaar Vintages", level = 11, minLevel = 8, objective = "Collect $1oa grapes.", desc = "[PH] Collect grapes from the vineyard" },
})

ns.AddQuests("z215", {
    { id = 96774, name = "Ancient Gurubashi Idol", level = 40, minLevel = 30, faction = "Horde", giver = "Mazu'kon", start = { npc = "Mazu'kon", area = 215, x = 34.1, y = 30.4 }, objective = "Recover an Ancient Gurubashi Idol from the Drowned City.", desc = "The ancient Gurubashi of Stranglethorn Vale were da masters of dark blood magics. Rumors be they'd use pure truesilver idols to channel that bad bad voodoo.\n\nOl' Mazu'kon would love to get his hands on one of those idols... for academics ya see. How 'bout you gather some friends and do a bit of smash and grab on that drowned city stickin' out the ocean off the coast of Stranglethorn? Kill the most impressive lookin' priest ya can find in there, and they sure to have what I be lookin' for." },
})

